import{_ as t,o as n,c as a,a2 as s}from"./chunks/framework.Cz0TtJv6.js";const h=JSON.parse('{"title":"Fees","description":"1% usage fee — buys and burns GNME on live winning closes.","frontmatter":{"title":"Fees","description":"1% usage fee — buys and burns GNME on live winning closes."},"headers":[],"relativePath":"fees.md","filePath":"fees.md","lastUpdated":1795266297000}'),o={name:"fees.md"};function r(i,e,l,c,d,p){return n(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="fees" tabindex="-1">Fees <a class="header-anchor" href="#fees" aria-label="Permalink to &quot;Fees&quot;">​</a></h1><p>DLMM Bot takes <strong>1% of measured profit</strong> on each <strong>live winning close</strong>. That cut buys and burns <a href="https://solscan.io/token/BaDjVCpABEVCdt4LT7ivuzA4izBwJCqnDjrLa8XBtT38" target="_blank" rel="noreferrer">GNME</a> — CryptoGnome’s existing token from <a href="https://www.gnmemining.com/" target="_blank" rel="noreferrer">GNME Mining</a>, a separate Solana mining game. The bot does not mint its own token; the fee supports that one.</p><p>Paper mode never spends. Losses and break-even closes are not charged. The fee is fixed product behavior, not a Settings toggle.</p><p>The fee is charged per winning close and shows up in that position&#39;s realized PnL, so every profit figure the bot and dashboard report is already net of it. Shares collect in a pot that is burned once it reaches 0.001 SOL: a smaller amount would cost about as much in network fees as it burns, so it waits for the next one. Nothing is waived.</p><p class="cta-row"><a class="doc-btn" href="https://www.gnmemining.com/" target="_blank" rel="noreferrer">GNME Mining</a><a class="doc-btn ghost" href="https://solscan.io/token/BaDjVCpABEVCdt4LT7ivuzA4izBwJCqnDjrLa8XBtT38" target="_blank" rel="noreferrer">GNME on Solscan</a></p>',5)])])}const g=t(o,[["render",r]]);export{h as __pageData,g as default};
